using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEditor;
using UnityEngine;

// Restore discrepant translation and rotation channels from native Unreal bone samples.
// Original FBX bytes remain intact; corrected clips are generated by the model importer.
public static class FpsPackTranslationRepair
{
    [Serializable] public class Bone { public string bone; public float[] values,rotations,scales; }
    [Serializable] public class Clip { public string source; public float duration; public int frames; public Bone[] bones; }
    [Serializable] public class Data { public Clip[] clips; }
    static Dictionary<string,Clip> sourcePoses;
    public static AnimationClip Apply(AnimationClip original,string source)
    {
        if(!original)return null;
        string pathToData=FpsPackPreviewCatalog.Root+"native-motion.json";
        if(sourcePoses==null || (sourcePoses.Count==0 && File.Exists(pathToData)))
        {
            string path=pathToData;
            sourcePoses=File.Exists(path)?JsonUtility.FromJson<Data>(File.ReadAllText(path)).clips.ToDictionary(c=>c.source):new Dictionary<string,Clip>();
        }
        if(!sourcePoses.TryGetValue(source,out var pose))return original;
        var bindings=AnimationUtility.GetCurveBindings(original);
        var paths=bindings.Select(b=>b.path).Distinct().Where(p=>p.Length>0).GroupBy(p=>p.Split('/').Last(),StringComparer.OrdinalIgnoreCase)
            .ToDictionary(g=>g.Key,g=>g.First(),StringComparer.OrdinalIgnoreCase);
        var replacements=new List<EditorCurveBinding>();var curves=new List<AnimationCurve>();
        foreach(var bone in pose.bones)
        {
            if(!paths.TryGetValue(bone.bone,out var path))continue;
            for(int axis=0;axis<3;axis++)
            {
                var binding=EditorCurveBinding.FloatCurve(path,typeof(Transform),"m_LocalPosition."+"xyz"[axis]);
                var imported=AnimationUtility.GetEditorCurve(original,binding);
                int count=bone.values.Length/3;
                float Value(int index)
                {
                    int component=axis==0?0:axis==1?2:1;
                    return bone.values[index*3+component]*.01f*(axis==2?-1:1);
                }
                float Time(int index)=>count==1?0:pose.duration*index/(count-1);
                bool differs=imported==null;
                if(!differs)
                {
                    if(count==1)differs=imported.keys.Any(k=>Mathf.Abs(k.value-Value(0))>.00005f);
                    else for(int i=0;i<count && !differs;i++)differs=Mathf.Abs(imported.Evaluate(Time(i))-Value(i))>.00005f;
                }
                if(!differs)continue;
                AnimationCurve corrected;
                if(count==1)corrected=AnimationCurve.Constant(0,pose.duration,Value(0));
                else
                {
                    // The source is sampled at 60 Hz; linear interpolation avoids invented overshoot.
                    var keys=new Keyframe[count];
                    for(int i=0;i<count;i++)
                    {
                        float incoming=i==0?0:(Value(i)-Value(i-1))/(Time(i)-Time(i-1));
                        float outgoing=i==count-1?incoming:(Value(i+1)-Value(i))/(Time(i+1)-Time(i));
                        keys[i]=new Keyframe(Time(i),Value(i),incoming,outgoing);
                    }
                    corrected=new AnimationCurve(keys);
                }
                replacements.Add(binding);curves.Add(corrected);
            }
        }
        foreach(var bone in pose.bones)
        {
            if(bone.rotations==null || bone.rotations.Length<4 || !paths.TryGetValue(bone.bone,out var path))continue;
            var rotationBindings="xyzw".Select(axis=>EditorCurveBinding.FloatCurve(path,typeof(Transform),"m_LocalRotation."+axis)).ToArray();
            var imported=rotationBindings.Select(b=>AnimationUtility.GetEditorCurve(original,b)).ToArray();
            if(imported.Any(curve=>curve==null))continue;
            int count=bone.rotations.Length/4;
            Quaternion Native(int index)
            {
                int start=index*4;var values=bone.rotations;
                return new Quaternion(values[start],values[start+2],-values[start+1],values[start+3]);
            }
            Quaternion Imported(float time)=>new Quaternion(imported[0].Evaluate(time),imported[1].Evaluate(time),imported[2].Evaluate(time),imported[3].Evaluate(time)).normalized;
            var offset=Quaternion.Inverse(Native(0))*Imported(0);
            var rotations=new Quaternion[count];bool differs=false;
            for(int i=0;i<count;i++)
            {
                rotations[i]=(Native(i)*offset).normalized;
                if(i>0 && Quaternion.Dot(rotations[i-1],rotations[i])<0)rotations[i]=new Quaternion(-rotations[i].x,-rotations[i].y,-rotations[i].z,-rotations[i].w);
                float time=count==1?0:pose.duration*i/(count-1);
                if(Quaternion.Angle(rotations[i],Imported(time))>.08f)differs=true;
            }
            if(count==1)differs=imported.SelectMany(curve=>curve.keys).Any(k=>Quaternion.Angle(rotations[0],Imported(k.time))>.08f);
            if(!differs)continue;
            for(int axis=0;axis<4;axis++)
            {
                AnimationCurve curve;
                if(count==1)curve=AnimationCurve.Constant(0,pose.duration,rotations[0][axis]);
                else
                {
                    var keys=new Keyframe[count];float step=pose.duration/(count-1);
                    for(int i=0;i<count;i++)
                    {
                        float incoming=i==0?0:(rotations[i][axis]-rotations[i-1][axis])/step;
                        float outgoing=i==count-1?incoming:(rotations[i+1][axis]-rotations[i][axis])/step;
                        keys[i]=new Keyframe(i*step,rotations[i][axis],incoming,outgoing);
                    }
                    curve=new AnimationCurve(keys);
                }
                replacements.Add(rotationBindings[axis]);curves.Add(curve);
            }
        }
        foreach(var bone in pose.bones)
        {
            if(bone.scales==null || bone.scales.Length<3 || !paths.TryGetValue(bone.bone,out var path))continue;
            int count=bone.scales.Length/3;
            for(int axis=0;axis<3;axis++)
            {
                int component=axis==0?0:axis==1?2:1;
                var binding=EditorCurveBinding.FloatCurve(path,typeof(Transform),"m_LocalScale."+"xyz"[axis]);
                var imported=AnimationUtility.GetEditorCurve(original,binding);
                float Value(int i)=>bone.scales[i*3+component];
                bool differs=imported==null;
                for(int i=0;i<count && !differs;i++)differs=Mathf.Abs(imported.Evaluate(count==1?0:pose.duration*i/(count-1))-Value(i))>.00001f;
                if(count==1 && imported!=null)differs=imported.keys.Any(k=>Mathf.Abs(k.value-Value(0))>.00001f);
                if(!differs)continue;
                AnimationCurve curve;
                if(count==1)curve=AnimationCurve.Constant(0,pose.duration,Value(0));
                else
                {
                    float step=pose.duration/(count-1);var keys=new Keyframe[count];
                    for(int i=0;i<count;i++)keys[i]=new Keyframe(i*step,Value(i),i==0?0:(Value(i)-Value(i-1))/step,i==count-1?0:(Value(i+1)-Value(i))/step);
                    curve=new AnimationCurve(keys);
                }
                replacements.Add(binding);curves.Add(curve);
            }
        }
        if(replacements.Count==0)return original;
        var result=UnityEngine.Object.Instantiate(original);result.name=original.name;result.hideFlags=HideFlags.HideAndDontSave;
        AnimationUtility.SetEditorCurves(result,replacements.ToArray(),curves.ToArray());
        return result;
    }
    public static void Release(AnimationClip clip)
    {
        if(clip && !AssetDatabase.Contains(clip))UnityEngine.Object.DestroyImmediate(clip);
    }
}
